struct Produit {
    std::string nom;
    int prix;
    int stock;
};

int nombreEnRupture(const std::vector<Produit>& produits, int seuil) {
    int n = 0;
    for (const Produit& p : produits) {
        if (p.stock < seuil) {
            n++;
        }
    }
    return n;
}

