solution:
#include <iostream>
#include <vector>
#include <string>

struct Produit {
    std::string nom;
    int prix;
    int stock;
};

int main() {
    int n;
    std::cin >> n;
    std::vector<Produit> produits;
    for (int i = 0; i < n; i++) {
        Produit p;
        std::cin >> p.nom >> p.prix >> p.stock;
        produits.push_back(p);
    }
    int valeur = 0;
    Produit cher = produits[0];
    for (const Produit& p : produits) {
        std::cout << p.nom << " : " << p.stock << " x " << p.prix << " FCFA\n";
        valeur += p.prix * p.stock;
        if (p.prix > cher.prix) {
            cher = p;
        }
    }
    std::cout << "Valeur totale : " << valeur << " FCFA\n";
    std::cout << "Produit le plus cher : " << cher.nom << "\n";
    return 0;
}
